        ...(nivel >= 13 ? [{ id:'deflect-energy', name:'Deflect Energy', source:'Monje · Nivel 13', type:'active', action:'Reacción', range:'Personal', recharge:null, desc:'Deflect Missiles ahora también funciona contra daño de energía (fuego, rayo, etc).', fullDesc:'' }] : []),
        ...(nivel >= 14 ? [{ id:'diamond-soul', name:'Diamond Soul', source:'Monje · Nivel 14', type:'passive', action:'Pasiva', range:'Personal', recharge:null, desc:'Proficiencia en todos los Saving Throws. Gastando 1 Ki repites una tirada de salvación fallida.', fullDesc:'' }] : []),
