        ...(nivel >= 16 ? [{ id:'monk-asi-16', name:'Ability Score Improvement', source:'Monje · Nivel 16', type:'passive', action:'Pasiva', range:'Personal', recharge:null, desc:'+2 a un stat o +1 a dos stats.', fullDesc:'' }] : []),
