        ...(nivel >= 3 ? [{ id:'sacred-oath', name:'Sacred Oath (Subclase)', source:'Paladín · Nivel 3', type:'passive', action:'Pasiva', range:'Personal', recharge:null, desc:'Eliges tu Juramento que define tus poderes divinos.', fullDesc:'' }] : []),
        ...(nivel >= 4 ? [{ id:'pal-asi-4', name:'Ability Score Improvement', source:'Paladín · Nivel 4', type:'passive', action:'Pasiva', range:'Personal', recharge:null, desc:'+2 a un stat o +1 a dos stats.', fullDesc:'' }] : []),
        ...(nivel >= 5 ? [{ id:'extra-attack-pal', name:'Extra Attack', source:'Paladín · Nivel 5', type:'passive', action:'Pasiva', range:'Personal', recharge:null, desc:'Al usar la acción Atacar, puedes atacar dos veces.', fullDesc:'' }] : []),
        ...(nivel >= 5 ? [{ id:'faithful-steed', name:'Faithful Steed', source:'Paladín · Nivel 5', type:'active', action:'Acción', range:'30 ft', recharge:'long', desc:'Conjuras un corcel (caballo, pony, mastín...) que comparte tu alineación. Se puede resumir tras morir.', fullDesc:'' }] : []),
        ...(nivel >= 6 ? [{ id:'aura-of-protection', name:'Aura of Protection', source:'Paladín · Nivel 6', type:'passive', action:'Pasiva', range:'10 ft', recharge:null, desc:`Tú y aliados a 10 ft suman tu mod CAR (mínimo +1) a todos los Saving Throws.`, fullDesc:'Mientras estés consciente, tú y las criaturas amigables a 10 pies de ti suman tu modificador de Carisma (mínimo +1) a todas las tiradas de salvación.' }] : []),
        ...(nivel >= 8 ? [{ id:'pal-asi-8', name:'Ability Score Improvement', source:'Paladín · Nivel 8', type:'passive', action:'Pasiva', range:'Personal', recharge:null, desc:'+2 a un stat o +1 a dos stats.', fullDesc:'' }] : []),
        ...(nivel >= 9 ? [{ id:'abjure-foes', name:'Abjure Foes', source:'Paladín · Nivel 9', type:'active', action:'Acción', range:'60 ft', recharge:'long', desc:`Hasta mod CAR criaturas hacen save SAB (tu CD) o quedan Asustadas e Incapacitadas 1 min. 1 uso/Long Rest.`, fullDesc:'' }] : []),
        ...(nivel >= 10 ? [{ id:'aura-of-courage', name:'Aura of Courage', source:'Paladín · Nivel 10', type:'passive', action:'Pasiva', range:'10 ft', recharge:null, desc:'Tú y aliados a 10 ft son inmunes al estado Frightened mientras estés consciente.', fullDesc:'' }] : []),
