        ...(nivel >= 12 ? [{ id:'pal-asi-12', name:'Ability Score Improvement', source:'Paladín · Nivel 12', type:'passive', action:'Pasiva', range:'Personal', recharge:null, desc:'+2 a un stat o +1 a dos stats.', fullDesc:'' }] : []),
        ...(nivel >= 14 ? [{ id:'cleansing-touch', name:'Cleansing Touch', source:'Paladín · Nivel 14', type:'active', action:'Acción', range:'Contacto', recharge:'long', desc:`Terminas un conjuro activo en una criatura que lo consienta. Mod CAR usos/Long Rest.`, fullDesc:'' }] : []),
