  // Arcane Trickster: la lista de Mago completa (el tope de nivel lo pone
  // getMaxSpellLevel; un Pícaro de otra subclase no llega a ningún nivel).
  CLASE_SPELLS['Pícaro'] = CLASE_SPELLS['Mago'];

  // Nivel de slot de Pact Magic según nivel de Brujo (PHB)
  const WARLOCK_SLOT_LEVEL = {
    1:1, 2:1, 3:2, 4:2, 5:3, 6:3, 7:4, 8:4, 9:5,
    10:5, 11:5, 12:5, 13:5, 14:5, 15:5, 16:5, 17:5, 18:5, 19:5, 20:5
  };

  /* ── PASSIVE_DAMAGE_FEATURES ────────────────────────────────────────────
     TABLA CURADA A MANO. Solo features cuyo `desc` real en este archivo es
     INEQUÍVOCO sobre cuántos dados, de qué tipo, y en qué contexto aplican.
     NUNCA se infiere nada parseando texto libre: si un featureId no está acá,
     no toca ningún cálculo (solo aparece en Novedades, como siempre).

     Forma: featureId → { dice, damageType, label, appliesTo, note, supersedes }
       appliesTo : ['spell'] | ['weapon'] | ['spell','weapon']
       supersedes: id de la versión básica que esta feature reemplaza
                   (para que nunca se sumen las dos)
     Los `dice` son fijos; cuando una feature escala con el nivel, el proyecto
     ya la modela como DOS ids distintos (ej. blessed-strikes / improved-
     blessed-strikes), así que acá van como entradas separadas con supersedes.
     Deliberadamente NO incluidas (ver reporte): sneak-attack, divine-smite,
     potent-spellcasting, y los Divine Strike de dominio que escalan dentro de
     un mismo id. */
  const PASSIVE_DAMAGE_FEATURES = {
    // Divine Strike (PHB 2024): solo al impactar con un arma, necrótico o
    // radiante a elección, una vez en cada uno de TUS turnos.
    'blessed-strikes': {
      dice: '1d8', damageType: 'necrótico o radiante', label: 'Divine Strike',
      appliesTo: ['weapon'], note: '1× en cada uno de tus turnos',
    },
    // Nv14: Divine Strike pasa a 2d8 "en lugar de" 1d8 → supersedes.
    'improved-blessed-strikes': {
      dice: '2d8', damageType: 'necrótico o radiante', label: 'Divine Strike mejorado',
      appliesTo: ['weapon'], note: '1× en cada uno de tus turnos',
      supersedes: 'blessed-strikes',
    },
    // Paladín nv11: "+1d8 daño radiante a tus ataques de arma y ataques
    // desarmados." Sin condición ni límite por turno → siempre aplica al arma.
    'radiant-strikes': {
      dice: '1d8', damageType: 'radiante', label: 'Radiant Strikes',
      appliesTo: ['weapon'], note: 'cada ataque de arma',
    },
  };

  // Devuelve los bonuses pasivos de daño activos del personaje para un
  // contexto dado ('spell' o 'weapon'). Solo mira la tabla curada; resuelve
  // supersedes para que la versión básica y la mejorada nunca se sumen.
  // Retorna [{ dice, damageType, label, note }].
  function getPassiveDamageBonuses(char, context) {
    if (!char || !context) return [];

    // Features activas: clase + subclase al nivel actual
    const active = [];
    const claseCfg = CLASE_FEATURES[char.clase];
    if (claseCfg && typeof claseCfg.features === 'function') {
      active.push(...claseCfg.features(char.nivel || 1));
    }
    if (char.subclase) {
      const subCfg = SUBCLASES_CONFIG[char.subclase];
      if (subCfg && typeof subCfg.features === 'function') {
        active.push(...subCfg.features(char.nivel || 1));
      }
    }

    const activeIds = new Set(active.map(f => f.id));
    // Blessed Strikes es una elección: con Potent Spellcasting no hay Divine Strike.
    const bs = char.choices && char.choices['blessed-strikes'];
    if ((bs && (bs.id || bs)) === 'bs-potent-spellcasting') {
      activeIds.delete('blessed-strikes'); activeIds.delete('improved-blessed-strikes');
    }

    // Ids que quedan anulados porque el personaje tiene su versión mejorada
    const superseded = new Set();
    activeIds.forEach(id => {
      const entry = PASSIVE_DAMAGE_FEATURES[id];
      if (entry && entry.supersedes) superseded.add(entry.supersedes);
    });

    const out = [];
    const seen = new Set();
    activeIds.forEach(id => {
      if (superseded.has(id) || seen.has(id)) return;
      const entry = PASSIVE_DAMAGE_FEATURES[id];
      if (!entry) return;
      if (!entry.appliesTo.includes(context)) return;
      seen.add(id);
      out.push({ dice: entry.dice, damageType: entry.damageType, label: entry.label, note: entry.note });
    });
    return out;
  }

  // ── calcMulticlassSlots: tabla oficial PHB de multiclase ──────────────────
  function calcMulticlassSlots(classes) {
    let casterLevels = 0;
    let warlockLevel = 0;

    for (const c of classes) {
      const cfg = CLASES_CONFIG[c.name];
      if (!cfg) continue;
      if (cfg.slotTable === 'full')    casterLevels += c.level;
      if (cfg.slotTable === 'half')    casterLevels += Math.floor(c.level / 2);
      if (cfg.slotTable === 'warlock') warlockLevel = Math.max(warlockLevel, c.level);
      // Tercio de lanzador por subclase (Arcane Trickster, Eldritch Knight)
      if (!cfg.slotTable && /^(Arcane Trickster|Eldritch Knight)$/.test(c.subclass || '')) {
        if (classes.length === 1) {
          const fila = _filaTercio(c.level || 1, true), res = {};
          for (let i = 1; i <= 9; i++) res[i] = { current: fila[i-1] || 0, max: fila[i-1] || 0 };
          return res;
        }
        casterLevels += Math.floor((c.level || 0) / 3);
      }
    }

    const baseRow = FULL_CASTER_SLOTS[casterLevels] || Array(9).fill(0);
    const result = {};
    for (let i = 1; i <= 9; i++) {
      result[i] = { current: baseRow[i-1] || 0, max: baseRow[i-1] || 0 };
    }

    // Pact Magic del Brujo: slots separados que se añaden a su nivel de slot correspondiente
    // PHB: Warlock pact slots no se mezclan con los slots de multiclase para recuperación,
    // pero sí comparten el pool de slots disponibles del mismo nivel
    if (warlockLevel > 0) {
      const pactCount = (WARLOCK_SLOTS[warlockLevel] || [1])[0] || 0;
      const pactLevel = WARLOCK_SLOT_LEVEL[warlockLevel] || 1;
      // Sumar los Pact Slots al nivel correspondiente
      result[pactLevel] = {
        current: (result[pactLevel]?.current || 0) + pactCount,
        max:     (result[pactLevel]?.max     || 0) + pactCount,
      };
    }
    return result;
  }

  // ── applyRaza: aplica rasgos de raza al objeto personaje ─────────────────
  // razaNombre: string, statBonus2/statBonus1: claves de stat (ej: 'con', 'des')
  function applyRaza(char, razaNombre, statBonus2, statBonus1) {
    const cfg = RAZAS_CONFIG[razaNombre];
    if (!cfg) return char;

    char.raza    = razaNombre;
    char.subraza = char.subraza || '';

    // Aplicar bonus +2 / +1 a los stats elegidos
    // En D&D 2024 estos bonos los da el Origen, no la raza.
    // Solo se aplican si se pasan explícitamente (compatibilidad con flujos viejos).
    if (statBonus2 && char.stats[statBonus2] !== undefined) {
      char.stats[statBonus2] += 2;
    }
    if (statBonus1 && char.stats[statBonus1] !== undefined && statBonus1 !== statBonus2) {
      char.stats[statBonus1] += 1;
    }

    // Velocidad
    char.velocidad = cfg.speed || 30;

    // Resistencias
    if (cfg.resistances && cfg.resistances.length) {
      char.resistances = [...new Set([...(char.resistances || []), ...cfg.resistances])];
    }

    // Proficiencias de habilidad
    if (cfg.skillProfs && cfg.skillProfs.length) {
      char.skillProfs = [...new Set([...(char.skillProfs || []), ...cfg.skillProfs])];
    }

    // Darkvision + rasgos base
    const traits = [];
    if (cfg.darkvision > 0) traits.push(`Visión en penumbra ${cfg.darkvision} m`);
    if (cfg.traits) traits.push(...cfg.traits);
    char.speciesTraits = traits.join('\n');

    // Idiomas: la especie no da ninguno en 2024; los 2 de origen se eligen aparte.
    char.languages = ['Común'];

    return char;
  }

  // ── applySubraza: aplica rasgos de subraza encima de la raza base ──────────
  function applySubraza(char, subrazaNombre) {
    if (!subrazaNombre || !char.raza) return char;
    const razaCfg = RAZAS_CONFIG[char.raza];
    if (!razaCfg || !razaCfg.subraces) return char;

    const sub = razaCfg.subraces.find(s => s.name === subrazaNombre);
    if (!sub) return char;

    char.subraza = subrazaNombre;

    // Sobreescribir velocidad si la subraza la cambia
    if (sub.speed) char.velocidad = sub.speed;

    // Sobreescribir darkvision si la subraza la mejora
    if (sub.darkvision) {
      const existing = char.speciesTraits || '';
      char.speciesTraits = existing.replace(/Visión en penumbra \d+ m/, `Visión en penumbra ${sub.darkvision} m`);
      if (!char.speciesTraits.includes('Visión en penumbra')) {
        char.speciesTraits = `Visión en penumbra ${sub.darkvision} m\n` + char.speciesTraits;
      }
    }

    // Agregar resistencias de subraza
    if (sub.resistances && sub.resistances.length) {
      char.resistances = [...new Set([...(char.resistances || []), ...sub.resistances])];
    }

    // Agregar proficiencias de habilidad de subraza
    if (sub.skillProfs && sub.skillProfs.length) {
      char.skillProfs = [...new Set([...(char.skillProfs || []), ...sub.skillProfs])];
    }

    // Agregar proficiencias de armas de subraza
    if (sub.weaponProfs && sub.weaponProfs.length) {
      char.weaponProfs = [...new Set([...(char.weaponProfs || []), ...sub.weaponProfs])];
    }

    // Agregar rasgos de subraza a speciesTraits
    if (sub.traits && sub.traits.length) {
      const existing = char.speciesTraits || '';
      char.speciesTraits = existing + (existing ? '\n' : '') + sub.traits.join('\n');
    }

    return char;
  }

